"""RESULTS.md for run 3 from scoring/field_table.json (scripts/score.py), spend*.json, levers.json and the raw checkpoints:
summary and deviations; the model x field capability table (holds / repeats only / does not hold / uncovered); the
per-field 5-of-9 verdict with the framing bound beside it; bands and predictions P1-P4; the reference and re-run arms;
null, coverage and non-canonical rates; per-arm gateway statistics (provider, reasoning tokens, truncations, cost);
per-corpus-arm verdicts; then the ruling drafts (ruling-drafts.md, hand-written) verbatim.

Usage: python -P experiments/2026-10-18-run3/scripts/results_md.py
"""
import json, os
HERE = os.path.dirname(os.path.abspath(__file__)); EXP = os.path.dirname(HERE)
FT = json.load(open(os.path.join(EXP, 'scoring', 'field_table.json'), encoding='utf-8'))
MODELS = json.load(open(os.path.join(EXP, 'models.json'), encoding='utf-8'))
T = FT['table']; P = T['pooled']; UNITS = [tuple(u) for u in FT['units']]; ARMS = FT['arms']; NEW = FT['new_arms']; REF = FT['reference']; SON = FT['voter_rerun']
SHORT = {'google/gemini-4-argon': 'Gemini 4 Argon', 'deepseek/deepseek-v4-pro-0813': 'DeepSeek V4 Pro', 'qwen/qwen3.8-2.4t-a95b': 'Qwen3.8 2.4T', 'meta-llama/llama-4-maverick': 'Llama 4 Maverick', 'mistralai/mistral-large-4-0': 'Mistral Large 4', 'openai/gpt-oss-120b': 'gpt-oss-120b', REF: 'Haiku 5.5 (ref)', SON: 'Sonnet 5.5 (re-run)'}
TAG = {'google/gemini-4-argon': 'N1', 'deepseek/deepseek-v4-pro-0813': 'N2', 'qwen/qwen3.8-2.4t-a95b': 'N3', 'meta-llama/llama-4-maverick': 'N4', 'mistralai/mistral-large-4-0': 'N5', 'openai/gpt-oss-120b': 'N6', REF: 'Ref', SON: 'Son'}
FIELD_OF = {u: (u.rsplit('.', 1)[0] if u.endswith(('.text', '.value', '.type')) else u) for u, s, v in UNITS}
DEC = {'holds': '**H**', 'repeats only': 'R', 'does not hold': '×', 'uncovered': 'U', 'pending': '?'}


def f(x): return '—' if x is None else f'{x:.2f}'


def spend(name):
    p = os.path.join(EXP, name)
    return json.load(open(p, encoding='utf-8')) if os.path.exists(p) else {'total_usd': 0.0, 'calls': 0, 'by_model': {}}


def main():
    sx, sp, sj = spend('spend.json'), spend('spend_pilot.json'), spend('spend_judge.json'); lev = FT['levers']; bands = FT['bands']; pred = FT['predictions']; st = FT['arm_stats']
    tot = sx['total_usd'] + sp['total_usd'] + sj['total_usd']
    stop = lev.get('stop_usd', MODELS['budget_usd'])
    L = ['# RESULTS — run 3, vendor breadth on the comparable tier (2026-10-18)\n']
    L.append('Generated by `scripts/results_md.py` from `scoring/field_table.json` (`scripts/score.py`), `spend*.json`, `levers.json` and the checkpoints under `raw/`. Pre-registration: `docs/discovery/ontology-crosswalk-2026-10/experiment-plan-run3.md`, frozen by commit `run 3 pre-registration frozen` (`974408e`) before any call. Thresholds, majority rule, 5-of-9 rule, bands and predictions are the frozen ones; nothing below was chosen after seeing the data. Nothing pushed.\n')
    L.append('## 0. Summary\n')
    n_ext = sum(c.get('calls', 0) for c in FT['counts'].values())
    L.append(f"150 texts (synthetic 50, conversational 50, Pepys 50; byte-identical to runs 1–2, sha256-checked) × 5 repeats × {len(ARMS)} arms = {n_ext:,} extraction calls through OpenRouter, plus {sp['calls']} pilot calls and {sj['calls']} judge calls. **Spend USD {tot:.2f}** against the stop in force USD {stop} (extraction {sx['total_usd']:.2f}, pilot {sp['total_usd']:.2f}, judge {sj['total_usd']:.2f}; OpenRouter billed cost).\n")
    L.append('| Arm | role | endpoint served | calls | valid | parse fail | missing keys | truncated | transport | provider mismatch | mean reasoning tok | mean out tok | USD |\n|---|---|---|---|---|---|---|---|---|---|---|---|---|')
    for m in ARMS:
        c = FT['counts'].get(m, {}); s = st.get(m, {}); cc = s.get('counts', {}); role = 'new arm (one of the 9)' if m in NEW else ('reference' if m == REF else 'voter re-run')
        L.append(f"| {TAG[m]} `{m}` | {role} | {', '.join(f'{k} {v}' for k, v in s.get('providers', {}).items())} | {c.get('calls', 0)} | {c.get('valid', 0)} | {cc.get('parse', 0)} | {cc.get('missing_keys', 0)} | {cc.get('truncated', 0)} | {cc.get('transport', 0)} | {cc.get('provider_mismatch', 0)} | {f(s.get('mean_reasoning_tokens'))} | {f(s.get('mean_output_tokens'))} | {s.get('usd', 0):.2f} |")
    L.append(f"\nJudge (`{MODELS['judge']['model']}` via the gateway, first-party endpoint): {sj['calls']} calls, USD {sj['total_usd']:.2f}; judged (text, unit) pairs: {FT['judged_units']}.\n")
    L.append(f"**Verdicts.** {sum(1 for u, s, v in UNITS if P[u]['verdict']['holds_across_market'])} of 19 comparable-tier fields hold across the market under the frozen 5-of-9 rule; failing: {', '.join('`' + FIELD_OF[u] + '`' for u, s, v in UNITS if not P[u]['verdict']['holds_across_market']) or 'none'}. **Predictions:** " + ', '.join(f"{k} {'held' if v['held'] else 'not held'}" for k, v in pred.items()) + '. Details §1–§3.\n')
    L.append('### 0.1 Deviations from the pre-registration (all logged before the main run, `levers.json`)\n')
    L.append('| # | Deviation | Why | Logged |\n|---|---|---|---|')
    ov = lev.get('endpoint_overrides', {})
    for mid, o in ov.items(): L.append(f"| R3-D1 | `{mid}` served by `{o['tag']}` ({o['provider_name']}) instead of the frozen first-party pin | {o['why']} | `levers.json`, before the main run |")
    L.append(f"| R3-D2 (withdrawn) | thinking disabled on the two Claude arms — attempted, then withdrawn | {lev.get('thinking_disabled_withdrawn', '')} | `levers.json`; the Haiku no-thinking pilot records stay in `raw/pilot/` |")
    L.append(f"| lever 1 | `reasoning: {{effort: low}}` on {', '.join('`' + m + '`' for m in lev.get('reasoning_low', []))}; `reasoning: {{max_tokens: N}}` on {', '.join(f'`{m}` ({n})' for m, n in lev.get('reasoning_max_tokens', {}).items()) or 'none'} | {lev.get('reasoning_low_why', '')} {lev.get('reasoning_max_tokens_why', '')} | pilot gate, plan §9 |")
    for h in lev.get('pilot_history', []): L.append(f"| pilot | {h['when']}{': projected total USD ' + str(h['projected_total_usd']) if h.get('projected_total_usd') else ''} | {h['note']} | `spend_pilot.json`, `raw/pilot/` |")
    L.append(f"| stop | stop in force USD {stop} | plan §9 levers 2–3 as applied (see STATUS.md) | `levers.json` |")
    L.append('')
    L.append('## 1. Model × field capability table (pooled, 150 texts; frozen thresholds and decision rule, plan §7)\n')
    L.append('Cell = repeatability / agreement with the voting majority / coverage → decision. **H** holds (both thresholds met), R repeats only (repeatability met, agreement not), × does not hold, U uncovered (< 50 % of texts with a non-null answer and a majority; counts as not held). Thresholds: coded / boolean κ ≥ 0.70 repeat, Cohen κ ≥ 0.40 agreement; free text judge-equivalence ≥ 0.80 / ≥ 0.60; `intensity.value` ICC ≥ 0.75 / ≥ 0.50. Majority = Sonnet 5.5 (this run) + gpt-6.1-sol + Kimi K2.6 (run 1; run-2 Arm B for `harm`); texts with no two voters agreeing are excluded (exclusion rate in §2). ᵇ borderline (within 0.05 of a threshold), ˢ sparse (null ≥ 90 %). The three voters count as holding by the run that classed the field; the Haiku reference and the Sonnet re-run are reported, never counted.\n')
    L.append('| Field (unit) | ' + ' | '.join(f'{TAG[m]} {SHORT[m]}' for m in NEW) + f' | **new arms holding** | {TAG[REF]} | {TAG[SON]} |')
    L.append('|---|' + '---|' * len(NEW) + '---|---|---|')
    for u, s, v in UNITS:
        r = P[u]; cells = []
        for m in NEW + [REF, SON]:
            a = r['arms'].get(m, {})
            cells.append(f"{f(a.get('repeat'))} / {f(a.get('agree'))} / {f(a.get('coverage'))} {DEC.get(a.get('decision'), '?')}" + ('ᵇ' if a.get('borderline') else '') + ('ˢ' if a.get('sparse') else ''))
        L.append(f"| `{FIELD_OF[u]}`{' (' + u.rsplit('.', 1)[1] + ')' if u != FIELD_OF[u] else ''} | " + ' | '.join(cells[:len(NEW)]) + f" | **{r['verdict']['new_arms_hold']} of {r['verdict']['new_arms_run']}** | {cells[len(NEW)]} | {cells[len(NEW) + 1]} |")
    L.append('\n## 2. Per-field verdict (5-of-9 rule) with the framing bound\n')
    L.append('"Comparable holds across the market" when ≥ 5 of the 9 models hold the field (the three voters + ≥ 2 of the 6 new arms). Framing bound (Q5) = Sonnet 5.5 under the 47-field run-1 prompt (7-field run-2 Arm B for `harm`) against Sonnet 5.5 under this 19-field prompt: Cohen κ (raw agreement) for coded / boolean, ICC for `intensity.value`, judge same-class rate (populated-only beside) for free text. A new arm whose agreement is at or above the bound cannot be said to disagree for vendor reasons. Pre-registered recommendation on failure: re-class `interpretive` (R17: Essential → Extended); the founder rules.\n')
    L.append('| Field | shape | holds (of 9) | new arms H / R / × / U | verdict | majority texts (excl.) | framing bound | cross-model among new arms | recommendation |\n|---|---|---|---|---|---|---|---|---|')
    for u, s, v in UNITS:
        r = P[u]; vd = r['verdict']; fr = r['framing']; mj = r['majority']
        ds = [r['arms'][m]['decision'] for m in NEW if m in r['arms']]
        frs = (f"κ {f(fr.get('kappa'))} (raw {f(fr.get('raw'))})" if 'kappa' in fr else (f"ICC {f(fr.get('icc'))}" if 'icc' in fr else f"{f(fr.get('rate'))} (populated {f(fr.get('rate_nonnull'))})"))
        cn = r['cross_new'] or {}; cns = f(cn.get('kappa', cn.get('icc', cn.get('rate'))))
        L.append(f"| `{FIELD_OF[u]}` | {s} | **{vd['total_hold']} of {vd['total_hold_of']}** | {ds.count('holds')} / {ds.count('repeats only')} / {ds.count('does not hold')} / {ds.count('uncovered')} | {'**holds**' if vd['holds_across_market'] else '**fails**'} | {mj.get('texts_with_majority')} ({f(mj.get('exclusion_rate'))}) | {frs} | {cns} | {vd['recommendation'] or '—'} |")
    L.append('\n## 3. Bands and predictions (plan §7)\n')
    L.append('Bands from the run-1 / run-2 baseline on these 19 fields: cheap-tier = repeatability met on ≤ 13 of 19 (Haiku 5.5 run 1: 11), voting = ≥ 17 (Sonnet 19, Kimi 19, gpt-6.1-sol 18), 14–16 between. Open-weight set for P1 (weights and licence public at freeze): ' + ', '.join(f'`{m}`' for m in FT['p1_set']) + '. Mistral Large 4 is announced open-weight but unreleased at freeze and is reported with the closed arms.\n')
    L.append('| Arm | weights | repeat met / 19 | agree met / 19 | holds | repeats only | uncovered | band |\n|---|---|---|---|---|---|---|---|')
    for m in ARMS:
        b = bands[m]; w = next((e.get('weights') for e in MODELS['extractors'].values() if e['model'] == m), '')
        L.append(f"| {TAG[m]} `{m}` | {w} | {b['repeat_met']} | {b['agree_met']} | {b['holds']} | {b['repeats_only']} | {b['uncovered']} | **{b['band']}** |")
    L.append('\n| # | Prediction (frozen) | Result | Evidence |\n|---|---|---|---|')
    L.append(f"| P1 | open-weight arms behave like the cheap tier (band cheap-tier and holds ≤ 10, each) | **{'held' if pred['P1']['held'] else 'not held'}** | per arm: " + ', '.join(f"`{m}` {'yes' if ok else 'no'} (repeat {bands[m]['repeat_met']}, holds {bands[m]['holds']})" for m, ok in pred['P1']['per_arm'].items()) + ' |')
    g = pred['P2']['gemini']; L.append(f"| P2 | Gemini in the voting band (≥ 17) and holds ≥ 15 | **{'held' if pred['P2']['held'] else 'not held'}** | repeat met {g['repeat_met']}, holds {g['holds']}, band {g['band']} |")
    L.append(f"| P3 | `action_tendency`, `scope`, `need` the first to fail 5-of-9; `primary`, `valence`, `attribution`, `bodily_sensation`, `summary` hold across ≥ 8 of 9 | **{'held' if pred['P3']['held'] else 'not held'}** | failing set: {', '.join('`' + FIELD_OF[u] + '`' for u in pred['P3']['failing_fields']) or 'none'}; first-three-in-failing-set {pred['P3']['first_to_fail_in_failing_set']}; robust-five ≥ 8: {pred['P3']['robust_five_hold_ge_8']}; hold counts: " + ', '.join(f"{k.split('.')[-1]} {v}" for k, v in pred['P3']['hold_counts'].items()) + ' |')
    L.append(f"| P4 | `intensity.value` null on ≥ 50 % of texts for ≥ 3 of 6 new arms | **{'held' if pred['P4']['held'] else 'not held'}** | " + ', '.join(f"`{m}` {'yes' if ok else 'no'} ({f(P['emotion.intensity.value']['arms'][m]['null_rate'])})" for m, ok in pred['P4']['per_arm_null_ge_50pct'].items()) + ' |')
    L.append('\n## 4. Null rate per arm × field (§8), with the voters\' run-1 repeatability for reference\n')
    L.append('| Field | ' + ' | '.join(TAG[m] for m in ARMS) + ' | majority null share |\n|---|' + '---|' * len(ARMS) + '---|')
    for u, s, v in UNITS:
        r = P[u]; L.append(f"| `{FIELD_OF[u]}` | " + ' | '.join(f(r['arms'].get(m, {}).get('null_rate')) for m in ARMS) + f" | {f(r['majority'].get('null_share_of_majority'))} |")
    L.append('\nNon-canonical rate (share of populated coded answers outside the recommended vocabulary): ' + '; '.join(f"`{FIELD_OF[u]}` " + ', '.join(f"{TAG[m]} {f(P[u]['arms'][m].get('noncanonical_rate'))}" for m in ARMS if P[u]['arms'].get(m, {}).get('noncanonical_rate') is not None) for u, s, v in UNITS if s in ('C', 'CL') and any(P[u]['arms'].get(m, {}).get('noncanonical_rate') for m in ARMS)) + '.\n')
    L.append('`intensity.value` coverage (texts with ≥ 1 number / texts with all five): ' + ', '.join(f"{TAG[m]} {P['emotion.intensity.value']['arms'][m]['texts_with_number']} / {P['emotion.intensity.value']['arms'][m]['repeat_texts_complete']}" for m in ARMS) + '.\n')
    L.append('## 5. Per corpus arm (holds of 9; pooled verdict decides)\n')
    L.append('| Field | pooled | synthetic | conversational | pepys |\n|---|---|---|---|---|')
    for u, s, v in UNITS:
        L.append(f"| `{FIELD_OF[u]}` | " + ' | '.join(f"{T[c][u]['verdict']['total_hold']} of {T[c][u]['verdict']['total_hold_of']}" + ('' if T[c][u]['verdict']['holds_across_market'] else ' ✗') for c in ('pooled', 'synthetic', 'conversational', 'pepys') if c in T) + ' |')
    L.append('\n## 6. Gateway statistics per arm\n')
    L.append('| Arm | pinned endpoint | served by | reasoning param sent | mean reasoning tokens | mean output tokens | mean latency s | truncated (max_tokens) | mean USD / call | USD |\n|---|---|---|---|---|---|---|---|---|---|')
    for m in ARMS:
        e = next(e for e in MODELS['extractors'].values() if e['model'] == m); s = st.get(m, {}); cc = s.get('counts', {})
        ov = lev.get('endpoint_overrides', {}).get(m); tag = ov['tag'] if ov else e['endpoint']['tag']
        rp = ('max_tokens ' + str(lev['reasoning_max_tokens'][m])) if m in lev.get('reasoning_max_tokens', {}) else ('effort low' if m in lev.get('reasoning_low', []) else 'none (default)')
        L.append(f"| {TAG[m]} `{m}` | `{tag}` | {', '.join(f'{k} {v}' for k, v in s.get('providers', {}).items())} | {rp} | {f(s.get('mean_reasoning_tokens'))} | {f(s.get('mean_output_tokens'))} | {f(s.get('mean_latency_s'))} | {cc.get('truncated', 0)} | {f(s.get('mean_cost_usd'))} | {s.get('usd', 0):.2f} |")
    L.append('\n## 7. Ruling drafts per field failing 5-of-9 (for the founder)\n')
    rp = os.path.join(EXP, 'ruling-drafts.md')
    L.append(open(rp, encoding='utf-8').read().strip() if os.path.exists(rp) else '_ruling-drafts.md not yet written_')
    L.append('')
    open(os.path.join(EXP, 'RESULTS.md'), 'w', encoding='utf-8', newline='\n').write('\n'.join(L) + '\n')
    print('RESULTS.md written; spend', round(tot, 2))


if __name__ == '__main__':
    main()
